package net.officefloor.hq.app.rate;

import java.math.RoundingMode;
import java.sql.Date;
import java.util.ArrayList;
import java.util.List;
import net.officefloor.hq.app.setting.Settings;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/**
 * The rates kept per sheet: per grade, one for each from-date (and at most one with none). A sheet is given its
 * parents' rates too, up to {@link Rate#LEVELS} up, each at its level.
 */
@Repository
public class Rates {

    private static final RowMapper<Rate> ROW = (rs, i) -> new Rate(rs.getString("grade"),
            rs.getBigDecimal("pct").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
            rs.getDate("from_date") == null ? null : rs.getDate("from_date").toLocalDate().toString(),
            rs.getDate("to_date") == null ? null : rs.getDate("to_date").toLocalDate().toString());

    private final JdbcTemplate jdbc;

    private final Settings settings;

    public Rates(JdbcTemplate jdbc, Settings settings) {
        this.jdbc = jdbc;
        this.settings = settings;
    }

    /** Every rate on the sheet, its own by grade then from-date (the one with none first), then its parents' by level. */
    public List<Rate> list(String sheet) {
        List<Rate> all = new ArrayList<>(own(sheet));
        String parent = settings.parent(sheet);
        for (int level = 1; level <= Rate.LEVELS && !parent.isEmpty(); level++) {
            for (Rate rate : own(parent)) {
                all.add(rate.up(level));
            }
            parent = settings.parent(parent);
        }
        return all;
    }

    /** The rates kept on the sheet itself, by grade then from-date (the one with none first). */
    public List<Rate> own(String sheet) {
        return jdbc.query("SELECT grade, pct, from_date, to_date FROM rate WHERE sheet = ? ORDER BY grade, from_key", ROW,
                sheet);
    }

    /** Sets the grade's rate from the from-date (through its to-date), replacing the one already there for that grade and from-date. */
    public void set(String sheet, RateInput input) {
        Date from = input.from() == null ? null : Date.valueOf(input.from());
        Date to = input.to() == null ? null : Date.valueOf(input.to());
        if (jdbc.update(
                "UPDATE rate SET pct = ?, to_date = ? WHERE sheet = ? AND grade = ? AND from_date IS NOT DISTINCT FROM ?",
                input.pct(), to, sheet, input.grade(), from) == 0) {
            jdbc.update("INSERT INTO rate (sheet, grade, pct, from_date, to_date) VALUES (?, ?, ?, ?, ?)", sheet,
                    input.grade(), input.pct(), from, to);
        }
    }
}
package net.officefloor.hq.app.rate;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.Comparator;
import java.util.List;

/**
 * A grade's rate on a sheet: a percent with two decimals, as the screen shows it, in force from its from-date
 * (yyyy-MM-dd; null when it applies from the beginning of time) through its to-date (null when it has no end). Its
 * level is the sheet it is kept on: 0 this sheet's own, 1 its parent's, 2 its parent's parent, up to {@link #LEVELS}.
 */
public record Rate(String grade, String pct, String from, String to, int level) {

    /** The most levels up a sheet's parents give it rates. */
    public static final int LEVELS = 3;

    /** A sheet's own rate. */
    public Rate(String grade, String pct, String from, String to) {
        this(grade, pct, from, to, 0);
    }

    /** This rate as one inherited from the levels up. */
    public Rate up(int levels) {
        return new Rate(grade, pct, from, to, level + levels);
    }

    /**
     * The percent the grade's rates give on a date: the one whose from-date is the latest on or before it, or null
     * when the date is before every rate the grade has, or after the to-date of that one. When a level gives none, the
     * next level up is used.
     */
    public static String on(List<Rate> rates, String grade, LocalDate date) {
        for (int level = 0; level <= LEVELS; level++) {
            String pct = on(rates, grade, date, level);
            if (pct != null) {
                return pct;
            }
        }
        return null;
    }

    private static String on(List<Rate> rates, String grade, LocalDate date, int level) {
        return rates.stream().filter((r) -> r.grade().equals(grade) && r.level() == level)
                .filter((r) -> r.from() == null || !LocalDate.parse(r.from()).isAfter(date))
                .max(Comparator.comparing((Rate r) -> r.from() == null ? LocalDate.MIN : LocalDate.parse(r.from())))
                .filter((r) -> r.to() == null || !LocalDate.parse(r.to()).isBefore(date))
                .map(Rate::pct).orElse(null);
    }

    /** An amount times a percent, divided by 100, in hundredths rounded half to even; null when there is no rate. */
    public static BigDecimal due(String amount, String pct) {
        return due(amount, pct, RoundingMode.HALF_EVEN);
    }

    /**
     * An amount times a percent, divided by 100, in hundredths rounded by the mode (on the magnitude, so a negative
     * amount rounds as its positive would); null when there is no rate.
     */
    public static BigDecimal due(String amount, String pct, RoundingMode rounding) {
        return pct == null ? null
                : new BigDecimal(amount).multiply(new BigDecimal(pct)).movePointLeft(2).setScale(2, rounding);
    }
}
package net.officefloor.hq.app.rate;

import java.math.RoundingMode;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

public class SaveRate {
    public void save(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val RateInput input,
            Rates rates, Audit audit, Rollup rollup) {
        apply(sheet, user, input, rates, audit, rollup);
    }

    /** Sets one rate as the form does, replacing the one for the same grade and from-date; the rate import uses it too. */
    static void apply(String sheet, String user, RateInput input, Rates rates, Audit audit, Rollup rollup) {
        Rollup.Snapshot before = rollup.take(sheet);
        rates.set(sheet, input);
        audit.record("RATE_SET sheet=" + sheet + " by=" + user + " grade=" + input.grade() + " rate="
                + input.pct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()
                + (input.from() == null ? "" : " from=" + input.from())
                + (input.to() == null ? "" : " to=" + input.to()));
        rollup.record(sheet, user, before);
    }
}
package net.officefloor.hq.app.rate;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestParam;

/** Sets each checked line, in order, exactly as the rate form's SaveRate does. */
public class SetImportedRates {
    public void set(@PathVariable("sheet") String sheet, @RequestParam("user") String user,
            @Val ImportedRates imported, Rates rates, Audit audit, Rollup rollup,
            ObjectResponse<RateImportResponse> response) {
        for (RateInput input : imported.lines()) {
            SaveRate.apply(sheet, user, input, rates, audit, rollup);
        }
        response.send(new RateImportResponse(imported.lines().size(), rates.list(sheet)));
    }
}
-- The sheet's rate for each grade: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet VARCHAR(200)  NOT NULL,
    grade VARCHAR(1)    NOT NULL,
    pct   DECIMAL(9, 2) NOT NULL,
    PRIMARY KEY (sheet, grade)
);
-- A rate may carry a from-date: a grade may have several rates, one per from-date, and a claim uses the one
-- whose from-date is the latest on or before its date. A null from-date applies from the beginning of time.
-- from_key is the from-date as compared, so there is one rate per sheet, grade and from-date (null included).
ALTER TABLE rate DROP PRIMARY KEY;
ALTER TABLE rate ADD COLUMN from_date DATE;
ALTER TABLE rate ADD COLUMN from_key DATE GENERATED ALWAYS AS (COALESCE(from_date, DATE '0001-01-01'));
CREATE UNIQUE INDEX rate_sheet_grade_from ON rate (sheet, grade, from_key);
-- A rate may carry a to-date: it applies through that date. A claim dated after the to-date of the rate that
-- would apply to it (no later rate being in force then) has no rate. A null to-date applies without end.
ALTER TABLE rate ADD COLUMN to_date DATE;
